import{_ as n,C as t,o as r,c as o,E as s,a2 as l}from"./chunks/framework.BdWD-ld-.js";const y=JSON.parse('{"title":"130 Cases Pass Overall. How Many Action Tasks Actually Pass?","description":"","frontmatter":{"title":"130 Cases Pass Overall. How Many Action Tasks Actually Pass?","article_type":"experiment-report","edition":"research-center","research_question":"已披露的总通过数与动作成功数，能否确定动作适用子集的完整通过数？","summary":"Overall passes and successful actions do not identify whole-case success in the action-eligible subset. Conditional enumeration of vendor-reported counts yields feasible ranges of 4–24, 5–24 and 0–7; the missing information is the joint case-level outcome.","sources":["https://caacgo.cresclab.com/benchmark/gemini-4-hydrogen-november-2026","https://caacgo.cresclab.com/benchmark","https://caacgo.cresclab.com/benchmark/november-2026","https://www.chatbase.co/benchmark/results","https://www.chatbase.co/benchmark"],"date":"2026-11-16","column":"digital-employee","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261116-006","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-16-sig-20261116-006-cover-2026-11-16.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/digital-employee/2026-11-16-sig-20261116-006.md","filePath":"en/digital-employee/2026-11-16-sig-20261116-006.md","lastUpdated":1794991269000}'),h={name:"en/digital-employee/2026-11-16-sig-20261116-006.md"};function d(c,e,p,g,u,k){const a=t("ArticleCover"),i=t("ArticleTableScroll");return r(),o("div",null,[s(a,{image:"/assets/covers/daily-2026-11-16-sig-20261116-006-cover-2026-11-16.png",kicker:"Research",title:"130 Cases Pass Overall. How Many Action Tasks Actually Pass?",summary:"Overall passes and successful actions do not identify whole-case success in the action-eligible subset. Conditional enumeration of vendor-reported counts yields feasible ranges of 4–24, 5–24 and 0–7; the missing information is the joint case-level outcome.",version:"2026-11-16",languageHref:"/zh/digital-employee/2026-11-16-sig-20261116-006",languageLabel:"中文"}),s(i,{language:"en"}),e[0]||(e[0]=l(`<h1 id="_130-cases-pass-overall-how-many-action-tasks-actually-pass" tabindex="-1">130 Cases Pass Overall. How Many Action Tasks Actually Pass? <a class="header-anchor" href="#_130-cases-pass-overall-how-many-action-tasks-actually-pass" aria-label="Permalink to &quot;130 Cases Pass Overall. How Many Action Tasks Actually Pass?&quot;">​</a></h1><p>A customer-service evaluation lists 130 fully correct cases out of 150 and all 24 lead or booking actions saved. An acceptance owner might read the second number as “all 24 action tasks were completed correctly.” Yet those two totals permit anything from 4 to 24 whole-case passes among the action-eligible cases. To evaluate that subset, actions and whole-reply outcomes must be matched case by case. Two constructed tables make the missing information concrete and show the minimum record to request.</p><h2 id="first-align-the-denominators-150-and-24" tabindex="-1">First align the denominators: 150 and 24 <a class="header-anchor" href="#first-align-the-denominators-150-and-24" aria-label="Permalink to &quot;First align the denominators: 150 and 24&quot;">​</a></h2><p>Crescendo Lab&#39;s CAAC Go website-agent report describes six fictional businesses and 150 customer messages. It holds the agent, instructions and tools constant while changing the model. Its whole-case criterion combines the right action, no unsupported business claims and the visitor&#39;s language, with agreement from two model graders. Saved actions are also counted separately. <a href="https://caacgo.cresclab.com/benchmark/gemini-4-hydrogen-november-2026" target="_blank" rel="noreferrer">Model comparison report</a></p><p>We use the report&#39;s three row labels and counts as inputs:</p><table tabindex="0"><thead><tr><th>Model row as named by the report</th><th style="text-align:right;">Whole-case passes / 150</th><th style="text-align:right;">Leads or bookings saved / 24</th></tr></thead><tbody><tr><td>Gemini 4 Hydrogen</td><td style="text-align:right;">130</td><td style="text-align:right;">24</td></tr><tr><td>Claude Fable 5.2</td><td style="text-align:right;">131</td><td style="text-align:right;">24</td></tr><tr><td>GPT-6 Astra</td><td style="text-align:right;">114</td><td style="text-align:right;">7</td></tr></tbody></table><p>Source: the vendor report above. Names identify source rows; we did not separately verify model-release identities or invoke these models. These are vendor-reported counts, not an independent rerun. The method index also says action checks use what the agent did rather than model grading. <a href="https://caacgo.cresclab.com/benchmark" target="_blank" rel="noreferrer">Method index</a></p><p>An action saved and a whole case passed are different observations. A successful save can coexist with an unsupported statement or the wrong reply language. Consequently, 24 successful actions need not mean 24 fully correct cases.</p><p>The calculation below has three explicit premises: the 150 cases and 24 action-eligible cases refer to the same evaluation set; whole-case success in an eligible case requires action success; and no additional independence or correlation between actions and reply quality is assumed. This is a calculation conditional on the disclosed definitions.</p><h2 id="identical-totals-can-conceal-different-subsets" tabindex="-1">Identical totals can conceal different subsets <a class="header-anchor" href="#identical-totals-can-conceal-different-subsets" aria-label="Permalink to &quot;Identical totals can conceal different subsets&quot;">​</a></h2><p>Consider the row with 130 whole-case passes and 24 successful actions. There are 126 other cases. Both allocations below are consistent with the two disclosed totals:</p><table tabindex="0"><thead><tr><th>Case group</th><th style="text-align:right;">Construction A: pass</th><th style="text-align:right;">Construction A: not fully correct</th><th style="text-align:right;">Construction B: pass</th><th style="text-align:right;">Construction B: not fully correct</th></tr></thead><tbody><tr><td>24 action-eligible cases</td><td style="text-align:right;">4</td><td style="text-align:right;">20</td><td style="text-align:right;">24</td><td style="text-align:right;">0</td></tr><tr><td>126 other cases</td><td style="text-align:right;">126</td><td style="text-align:right;">0</td><td style="text-align:right;">106</td><td style="text-align:right;">20</td></tr><tr><td>All 150 cases</td><td style="text-align:right;">130</td><td style="text-align:right;">20</td><td style="text-align:right;">130</td><td style="text-align:right;">20</td></tr></tbody></table><p>Source: two extremal feasible tables from the current internal arithmetic experiment. In both constructions, all 24 eligible actions succeed. In A, 20 cases can nevertheless fail other reply requirements. These are possible allocations, not recovered conversations or measured failures.</p><p>Construction A places all 20 whole-case failures inside the action subset; B places all of them outside it. Both retain 130 overall passes and 24 action successes. Marginal counts—separately aggregated counts without their case-level intersection—cannot distinguish the two.</p><p>The true allocation could be B. The finding is that the subset&#39;s result is unidentified, not that the subset performed poorly. Reporting the worst feasible value as an actual vendor score would make exactly the unsupported inference this experiment is meant to prevent.</p><h2 id="these-bounds-come-from-capacity-not-sampling-error" tabindex="-1">These bounds come from capacity, not sampling error <a class="header-anchor" href="#these-bounds-come-from-capacity-not-sampling-error" aria-label="Permalink to &quot;These bounds come from capacity, not sampling error&quot;">​</a></h2><p>Let N be the case count, E the action-eligible count, P the overall whole-case pass count, S the successful-action count, and x the number of eligible cases that fully pass. Other cases can hold at most N−E passes, so at least P−(N−E) passes must fall in the eligible subset. Meanwhile x cannot exceed E, P or S.</p><p>For the compatible inputs used here, the feasible integer range is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>max(0, P - (N - E)) ≤ x ≤ min(E, P, S)</span></span></code></pre></div><p>The current research analysis already executed the internal enumeration: check every integer x, require nonnegative group counts and consistent totals, and require action success for a whole-case pass. This article reuses that completed experiment and performs no new model evaluation.</p><table tabindex="0"><thead><tr><th>Input row, in the same order as above</th><th style="text-align:right;">Feasible eligible whole-case passes</th><th style="text-align:right;">Compatible integer allocations</th></tr></thead><tbody><tr><td>130 passes, 24 action successes</td><td style="text-align:right;">4–24</td><td style="text-align:right;">21</td></tr><tr><td>131 passes, 24 action successes</td><td style="text-align:right;">5–24</td><td style="text-align:right;">20</td></tr><tr><td>114 passes, 7 action successes</td><td style="text-align:right;">0–7</td><td style="text-align:right;">8</td></tr></tbody></table><p>Source: current internal experiment; see the <a href="/joinwell52/assets/evidence/2026-11-16-sig-20261116-006/conditional-counts.json">conditional enumeration results</a>. The denominator for each subset is 24. The third row shows what the action count adds: 114 overall passes alone allow 0–24 eligible passes. Seven successful actions, together with the necessary-action premise, reduce the upper bound to 7.</p><p>These are feasibility bounds, not confidence intervals. Values inside them are not assigned equal probabilities, and the calculation says nothing about grader accuracy. The equivalent short form below lets readers check the existing experiment&#39;s core enumeration; it checks arithmetic and does not contact a vendor system:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> feasible_counts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(N, E, P, S):</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> range</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(E </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">            if</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> P </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> N </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> E </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">and</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> S]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">assert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> feasible_counts(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">150</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">24</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">130</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">24</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> list</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">range</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">25</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">assert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> feasible_counts(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">150</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">24</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">131</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">24</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> list</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">range</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">25</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">assert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> feasible_counts(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">150</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">24</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">114</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> list</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">range</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><p>This short form applies only when the inputs themselves satisfy 0≤S≤E≤N and 0≤P≤N, and whole-case success really requires action success. All three inputs here satisfy those constraints.</p><h2 id="another-evaluation-separates-stages-but-supplies-no-purchase-result" tabindex="-1">Another evaluation separates stages, but supplies no purchase result <a class="header-anchor" href="#another-evaluation-separates-stages-but-supplies-no-purchase-result" aria-label="Permalink to &quot;Another evaluation separates stages, but supplies no purchase result&quot;">​</a></h2><p>Chatbase&#39;s separately authored evaluation offers a useful methodological contrast. Its photo-shopping test distinguishes taking the photo, finding the product, adding it to the cart and reaching checkout. It reports 9/9 tested stores for its own agent at every stage. Other products have different sample denominators, with some stages marked unsupported. The units are stores and stages reached, so these figures cannot be inserted into the 150-case calculation. <a href="https://www.chatbase.co/benchmark/results" target="_blank" rel="noreferrer">Full results</a></p><p>Separating stages is easier to interpret than collapsing them into “completion,” but reaching checkout still supplies no payment or purchase count. We fill that missing count with neither zero nor nine. The comparison establishes a measurement boundary: observing one step can leave the next outcome unknown.</p><p>The reports have distinct responsible authors, populations and methods. They are two independent sources, not two experiments validating each other. One controls models within an agent; the other observes storefront deployments. Their scores cannot be pooled into a universal ranking. Two model graders or several reports from one vendor do not create more independent authoring actors. <a href="https://www.chatbase.co/benchmark" target="_blank" rel="noreferrer">Chatbase method overview</a></p><h2 id="what-the-next-evaluation-table-should-retain" tabindex="-1">What the next evaluation table should retain <a class="header-anchor" href="#what-the-next-evaluation-table-should-retain" aria-label="Permalink to &quot;What the next evaluation table should retain&quot;">​</a></h2><p>Our engineering recommendation is to preserve joint case-level records before aggregating. For a case requiring a booking request to be saved, record separately whether the action applies, whether the save succeeds and whether the whole reply passes. A shared case identifier makes the target subset directly countable. Acceptance of the actual booking is a separate downstream observation.</p><table tabindex="0"><thead><tr><th>Stage and input</th><th>Proposed responsible party</th><th>Output to retain</th><th>Condition preventing a completion claim</th></tr></thead><tbody><tr><td>Case and intended task</td><td>Evaluation designer</td><td>Action eligibility and expected action</td><td>Eligibility undefined</td></tr><tr><td>Case execution</td><td>Executor and action recorder</td><td>Action outcome and matching record</td><td>A verbal promise without an action record</td></tr><tr><td>Whole-reply assessment</td><td>Grader and adjudicator</td><td>Per-case pass and reason</td><td>Missing grade or inconsistent criterion</td></tr><tr><td>Join the outcomes for the same case</td><td>Evaluation aggregator</td><td>Eligible whole-case pass count</td><td>Unmatched cases or marginal totals only</td></tr><tr><td>Delivery of booking request or lead</td><td>Receiving business owner</td><td>Separate receipt, durable-save or fulfillment result</td><td>Business receipt or final outcome unobserved</td></tr></tbody></table><p>This is a proposed responsibility chain, not a description of either vendor&#39;s implemented system. A practical ledger should also retain the evaluation version and regrading history to prevent totals from different rounds being combined. The source, for example, describes a changed third-row count after regrading; we use 114 from the current report rather than mixing versions. <a href="https://caacgo.cresclab.com/benchmark/gemini-4-hydrogen-november-2026" target="_blank" rel="noreferrer">Regrading and method limitations</a></p><p>Where eligibility, action and whole-case outcomes are already joined, this identification problem does not apply: x can be counted directly. Nor should the grouping be forced onto an answer-only evaluation with no action subset.</p><h2 id="where-the-evidence-stops" tabindex="-1">Where the evidence stops <a class="header-anchor" href="#where-the-evidence-stops" aria-label="Permalink to &quot;Where the evidence stops&quot;">​</a></h2><p>The external materials are two commercial actors&#39; disclosures about their own methods and results. They establish what each report states, not independent confirmation of its scores. The internal experiment checks possible allocations under the stated premises; it accesses no raw conversations, grading prompts, customer records or real transactions. The full experimental record remains local. The attached <a href="/joinwell52/assets/evidence/2026-11-16-sig-20261116-006/conditional-counts.json">de-identified count results</a> retain the inputs, assumptions, all feasible tables and boundaries for arithmetic inspection, with no customer data.</p><p>The source also describes single runs, missing grades and regrading. Its linked method says a production lead-capture fallback is disabled in the test. Test action omissions therefore cannot be read directly as production loss rates. <a href="https://caacgo.cresclab.com/benchmark/gemini-4-hydrogen-november-2026" target="_blank" rel="noreferrer">Model report</a>, <a href="https://caacgo.cresclab.com/benchmark/november-2026" target="_blank" rel="noreferrer">linked method</a></p><p>What is missing is a record answering two questions: which action-eligible cases fully passed, and who confirmed receipt or fulfillment after the save? The first ends the arithmetic ambiguity examined here. The second is needed before discussing the corresponding business outcome.</p>`,38))])}const b=n(h,[["render",d]]);export{y as __pageData,b as default};
